    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base: residual after placement
    let mut score = post_residual as f64;

    // 1. Residual ratio squared – tighter packing
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * res_ratio.powi(2);

    // 2. Small‑gap penalty
    if post_residual < 3 {
        score += 200.0 * (3 - post_residual) as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 * (next_item_size - post_residual) as f64;
    }

    // 3. Look‑ahead waste penalty
    if next_item_size > 0
        && post_residual > next_item_size
        && (post_residual - next_item_size) < 1
    {
        score += 60.0;
    }

    // 4. Mean‑residual alignment
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.4 * diff;
    } else {
        score -= 0.3 * (-diff);
    }

    // 5. Open‑bin pressure relative to stream length
    if open_bins_count > 8 {
        score += 7.0 * ((open_bins_count - 8) as f64);
    }

    // 6. End‑of‑stream cost
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score += 2.5 * post_residual as f64;
    }

    // 7. Fitting‑bin count signal
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 3 {
        score += 4.0;
    }

    // 8. New‑bin bias for large items
    if bin_residual == bin_capacity {
        if item_size > 90 {
            score -= 35.0;
        } else if item_size > 60 {
            score -= 8.0;
        } else {
            score += 2.0;
        }
    }

    // 9. Quadratic penalty for deviation from mean
    score += 0.15 * diff * diff;

    // 10. Residual squared contribution
    score += 0.03 * (post_residual as f64).powi(2);

    // 11. Bin‑residual size signal
    let residual_pct = bin_residual as f64 / bin_capacity as f64;
    if residual_pct > 0.8 && item_size <= bin_residual {
        score -= 3.0;
    } else if residual_pct < 0.2 && item_size > bin_residual {
        score += 5.0;
    }

    // 12. Ideal‑residual bias – ~35% residual
    let ideal_residual = bin_capacity as f64 * 0.35;
    let idle = (post_residual as f64 - ideal_residual).abs();
    if idle > 4.0 {
        score += 0.08 * idle;
    }

    // 13. Late‑stage new‑bin pressure
