        score += 3.0;
    }

    // 14. Final aggressive closing near end
    if total_items - step_index < 3 && open_bins_count > 1 {
        score += 3.0 * ((open_bins_count - 1) as f64);
    }

    // 15. Look‑ahead fit reward
    if next_item_size > 0 && bin_residual - item_size >= next_item_size {
        score -= 4.0;
