    // 12. Late‑stage new‑bin pressure
    if open_bins_count > 1 && bin_residual < 10 && item_size > bin_residual {
        score += 2.5;
    }

    // ------------------------------------------------------------------
    // 13. Aggressive closing near end
    if total_items - step_index < 4 && open_bins_count > 1 {
        score += 3.5 * ((open_bins_count - 1) as f64);
    }

    // ------------------------------------------------------------------
    // 14. Look‑ahead fit reward (leaving space for next item)
    if next_item_size > 0 && bin_residual - item_size >= next_item_size + 4 {
        score -= 6.0;
    }

    // ------------------------------------------------------------------
    // 15. No‑fit penalty
    if fitting_bins_count == 0 {
