}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ------------------------------------------------------------------
    // 1. Base score: residual after placement (higher is worse)
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 2. Residual ratio penalty (encourage tighter packing)
    let ratio = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * ratio.powi(2) + 1.5 * ratio;

    // ------------------------------------------------------------------
    // 3. Look‑ahead waste penalty / reward
    if next_item_size > 0 {
        let slack_next = post_residual as i32 - next_item_size as i32;
        if slack_next < 0 {
            // Not enough space for next item – heavy penalty
            score += 60.0 * (-slack_next) as f64;
        } else if slack_next > 6 {
            // Plenty of space – small reward
            let slack = slack_next as f64;
            score -= 20.0 * slack / bin_capacity as f64;
        }
    }

    // ------------------------------------------------------------------
    // 4. Mean‑residual alignment (reduce variance)
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.5 * diff;
    } else {
        score -= 0.7 * (-diff);
    }

    // ------------------------------------------------------------------
    // 5. Open‑bin pressure (discourage many partially‑filled bins)
    if open_bins_count > 5 {
        score += 4.0 * ((open_bins_count - 5) as f64);
    } else if open_bins_count > 2 {
        score += 1.5 * ((open_bins_count - 2) as f64);
    }

    // ------------------------------------------------------------------
    // 6. End‑of‑stream cost (encourage tighter packing near the end)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.90 {
        score += 2.5 * post_residual as f64;
    }

    // ------------------------------------------------------------------
    // 7. Fitting‑bin count signal (more options = better)
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 4.0;
    }

    // ------------------------------------------------------------------
    // 8. New‑bin bias for large items
    if bin_residual == bin_capacity {
        if item_size > 90 {
            score -= 50.0;
        } else if item_size > 70 {
            score -= 15.0;
        } else {
            score += 2.0;
        }
    }

    // ------------------------------------------------------------------
    // 9. Residual squared contribution (penalise large slack)
    score += 0.015 * (post_residual as f64).powi(2);

    // ------------------------------------------------------------------
    // 10. Residual pct signal (reward high utilisation)
    let residual_pct = bin_residual as f64 / bin_capacity as f64;
    if residual_pct > 0.80 && item_size <= bin_residual {
        score -= 5.0;
    } else if residual_pct < 0.20 && item_size > bin_residual {
        score += 5.0;
    }

    // ------------------------------------------------------------------
    // 11. Ideal‑residual bias – target ~50% utilisation
    let target_residual = bin_capacity as f64 * 0.50;
    let idle = (post_residual as f64 - target_residual).abs();
    if idle > 6.0 {
        score += 0.08 * idle;
    }

    // ------------------------------------------------------------------
    // 12. Late‑stage new‑bin pressure
    if open_bins_count > 2 && bin_residual < 5 && item_size > bin_residual {
        score += 3.0;
    }

    // ------------------------------------------------------------------
    // 13. Final aggressive closing near end
    if total_items - step_index <= 3 && open_bins_count > 1 {
        score += 2.0 * (open_bins_count as f64);
    }

    // ------------------------------------------------------------------
    // 14. Look‑ahead fit reward (leaving space for next item)
    if next_item_size > 0 && bin_residual - item_size >= next_item_size + 3 {
        score -= 4.0;
    }

    // ------------------------------------------------------------------
    // 15. No‑fit penalty
    if fitting_bins_count == 0 {
        score += 10.0;
    }

    // ------------------------------------------------------------------
    // 16. Excess slack penalty
    if post_residual as f64 > mean_residual * 1.6 {
        score += 0.015 * (post_residual as f64 - mean_residual * 1.6);
    }

    // ------------------------------------------------------------------
    // 17. Tightness factor (how close we fit the item)
    let slack_before = bin_residual as i32 - item_size as i32;
    if slack_before >= 0 {
        if slack_before < 3 {
            score -= 1.0;
        } else if slack_before > 10 {
            score += 1.5;
        }
    }

    // ------------------------------------------------------------------
    // 18. Bin density bonus/penalty
    let used = bin_capacity - post_residual;
    let density = used as f64 / bin_capacity as f64;
    if density > 0.90 {
        score -= 2.0;
    } else if density < 0.50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(
