) -> f64 {
    // Base score: residual after placement
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 1. Residual ratio squared (tighter packing)
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * res_ratio.powi(2);

    // ------------------------------------------------------------------
    // 2. Small‑gap penalty (weaker than before)
    if post_residual < 2 {
        score += 500.0 * (2 - post_residual) as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 100.0 * (next_item_size - post_residual) as f64;
    }

    // ------------------------------------------------------------------
    // 3. Look‑ahead waste penalty
    if next_item_size > 0
        && post_residual > next_item_size
        && (post_residual - next_item_size) < 2
    {
        score += 80.0;
    }

    // ------------------------------------------------------------------
    // 4. Mean‑residual alignment
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.3 * diff;
    } else {
        score -= 0.2 * (-diff);
    }

    // ------------------------------------------------------------------
    // 5. Open‑bin pressure
    if open_bins_count > 5 {
        score += 5.0 * ((open_bins_count - 5) as f64);
    }
    if open_bins_count > 9 {
        score += 8.0 * ((open_bins_count - 9) as f64);
    }

    // ------------------------------------------------------------------
    // 6. End‑of‑stream cost
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score += 3.0 * post_residual as f64;
    }

    // ------------------------------------------------------------------
    // 7. Fitting‑bin count signal
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 4 {
