            score -= 40.0;
        } else if item_size > 70 {
            score -= 10.0;
        } else {
            score += 3.0;
        }
    }

    // ------------------------------------------------------------------
    // 9. Quadratic penalty for deviation from mean
    score += 0.1 * diff * diff;

    // ------------------------------------------------------------------
    // 10. Residual squared contribution
    score += 0.04 * (post_residual as f64).powi(2);

    // ------------------------------------------------------------------
    // 11. Bin‑residual size signal
    let residual_pct = bin_residual as f64 / bin_capacity as f64;
    if residual_pct > 0.75 && item_size <= bin_residual {
        score -= 4.0;
    } else if residual_pct < 0.25 && item_size > bin_residual {
        score += 6.0;
    }

    // ------------------------------------------------------------------
    // 12. Ideal‑residual bias – prefer ~40% residual
    let ideal_residual = bin_capacity as f64 * 0.40;
    let idle = (post_residual as f64 - ideal_residual).abs();
    if idle > 5.0 {
        score += 0.10 * idle;
    }

    // ------------------------------------------------------------------
    // 13. Late‑stage new‑bin pressure
    if open_bins_count > 3 && bin_residual < 10 && item_size > bin_residual {
        score += 4.0;
    }

    // ------------------------------------------------------------------
    // 14. Final aggressive closing near end
    if total_items - step_index < 4 && open_bins_count > 2 {
        score += 3.5 * ((open_bins_count - 2) as f64);
    }

    // ------------------------------------------------------------------
    // 15. Look‑ahead fit reward (leaving space for next item)
    if next_item_size > 0 && bin_residual - item_size >= next_item_size {
        score -= 5.0;
    }

    // ------------------------------------------------------------------
    // 16. No‑fit penalty
    if fitting_bins_count == 0 {
        score += 12.0;
    }

    score
}

